  saving = false;

  ngOnInit(): void {
    this.name = this.manufacturer?.name ?? '';
  }

  save(): void {
    if (this.saving) {
      return;
    }
    const draft: ManufacturerDto = { ...(this.manufacturer ?? { id: null, name: '', cars: [] }), name: this.name };
    this.saving = true;
    this.api.saveManufacturer(draft).subscribe({
      next: (saved) => {
        this.messages.success('The manufacturer has been saved.');
        this.saved.emit(saved);
      },
      error: (error: unknown) => {
        this.saving = false;
        this.messages.error(`The manufacturer could not be saved (${describeApiError(error)}).`);
      },
    });
  }

  close(): void {
    this.closed.emit();
  }
}
