    }
    .grid {
      width: 100%;
      border-collapse: collapse;
    }
    .grid th,
    .grid td {
      text-align: left;
      padding: 6px 8px;
      border-bottom: 1px solid #ddd;
    }
    .grid th {
      background: #f3f3f3;
    }
    .id-column {
