export class ManufacturersComponent implements OnInit {
  private readonly api = inject(CarStoreApi);
  private readonly messages = inject(MessageService);

  manufacturers: ManufacturerDto[] = [];
  /** The table is only rendered once the list has arrived, so waiting for it waits for the rows. */
  loaded = false;

  /** Open editor; `manufacturer` is null when creating. Null while the popup is closed. */
  editor: { manufacturer: ManufacturerDto | null } | null = null;

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (manufacturers) => {
        this.manufacturers = manufacturers;
        this.loaded = true;
      },
      error: () => {
        this.loaded = true;
        this.messages.error('The manufacturers could not be loaded.');
      },
    });
  }

  create(): void {
    this.editor = { manufacturer: null };
  }

  edit(manufacturer: ManufacturerDto): void {
    this.editor = { manufacturer };
  }

  closeEditor(): void {
    this.editor = null;
  }

  onSaved(saved: ManufacturerDto): void {
    const index = this.manufacturers.findIndex((manufacturer) => manufacturer.id === saved.id);
    if (index >= 0) {
      // Edit: replace in place so the row keeps its position, as GWT's replaceManufacturer does.
      this.manufacturers = this.manufacturers.map((manufacturer, i) => (i === index ? saved : manufacturer));
    } else {
      this.manufacturers = [...this.manufacturers, saved];
    }
    this.editor = null;
  }

  remove(manufacturer: ManufacturerDto): void {
    if (manufacturer.id === null) {
      return;
    }
    if (!window.confirm(`Are you sure you want to delete ${manufacturer.name}?`)) {
      return;
    }
    const id = manufacturer.id;
    this.api.deleteManufacturer(id).subscribe({
      next: () => (this.manufacturers = this.manufacturers.filter((m) => m.id !== id)),
      error: () => this.messages.error(`The manufacturer ${manufacturer.name} could not be deleted.`),
    });
  }
}
