export class EditRatingComponent implements OnInit {
  private readonly api = inject(CarStoreApi);
  private readonly messages = inject(MessageService);

  @Output() readonly saved = new EventEmitter<RatingDto>();
  @Output() readonly closed = new EventEmitter<void>();

  cars: CarDto[] = [];
  loaded = false;
  carId: number | null = null;
  rating: number | null = null;
  saving = false;

  readonly carLabel = carOptionLabel;

  ngOnInit(): void {
    this.api.getCars().subscribe({
      next: (cars) => {
        this.cars = cars;
        this.carId = cars[0]?.id ?? null;
        this.loaded = true;
      },
      error: (error: unknown) => {
        this.messages.error(`The cars could not be loaded (${describeApiError(error)}).`);
        this.close();
      },
    });
  }

  canSave(): boolean {
    return this.loaded && !this.saving && this.carId !== null && this.rating !== null && Number.isInteger(this.rating);
  }

  save(): void {
    const car = this.cars.find((c) => c.id === this.carId);
    if (!this.canSave() || !car || this.rating === null) {
      return;
    }
    const draft: RatingDto = { id: null, rating: this.rating, car };
    this.saving = true;
    this.api.saveRating(draft).subscribe({
      next: (saved) => {
        this.messages.success('The rating has been saved.');
        this.saved.emit(saved);
      },
      error: (error: unknown) => {
        this.saving = false;
        this.messages.error(`The rating could not be saved (${describeApiError(error)}).`);
      },
    });
  }

  close(): void {
    this.closed.emit();
  }
}
