import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

import { CarDto, ManufacturerDto, ManufacturerRatingDto, RatingDto } from './models';

/** Client for the existing JAX-RS API (paths from shared/api/ApiPaths.java). */
@Injectable({ providedIn: 'root' })
export class CarStoreApi {
  private readonly http = inject(HttpClient);

  private static readonly ROOT = '/api';

  getManufacturers(): Observable<ManufacturerDto[]> {
    return this.http.get<ManufacturerDto[]>(`${CarStoreApi.ROOT}/manufacturers`);
  }

  /** POST creates when id is null, otherwise updates (ManufacturersResource.saveOrCreate). */
  saveManufacturer(manufacturer: ManufacturerDto): Observable<ManufacturerDto> {
    return this.http.post<ManufacturerDto>(`${CarStoreApi.ROOT}/manufacturers`, manufacturer);
  }

  deleteManufacturer(id: number): Observable<void> {
    return this.http.delete<void>(`${CarStoreApi.ROOT}/manufacturers/${id}`);
  }

  getAverageRatings(): Observable<ManufacturerRatingDto[]> {
    return this.http.get<ManufacturerRatingDto[]>(`${CarStoreApi.ROOT}/manufacturers/ratings`);
  }

  getRatings(): Observable<RatingDto[]> {
    return this.http.get<RatingDto[]>(`${CarStoreApi.ROOT}/ratings`);
  }

  saveRating(rating: RatingDto): Observable<RatingDto> {
    return this.http.post<RatingDto>(`${CarStoreApi.ROOT}/ratings`, rating);
  }

  deleteRating(id: number): Observable<void> {
    return this.http.delete<void>(`${CarStoreApi.ROOT}/ratings/${id}`);
  }

  /** CarsResource.LIMIT_ALL is -1; the GWT rating editor asks for all cars the same way. */
  getCars(): Observable<CarDto[]> {
    return this.http.get<CarDto[]>(`${CarStoreApi.ROOT}/cars`, {
      params: { offset: 0, limit: -1 },
    });
  }
}
