import { Injectable, signal } from '@angular/core';

export type MessageStyle = 'success' | 'error';

export interface AppMessage {
  readonly id: number;
  readonly style: MessageStyle;
  readonly text: string;
}

/** Same auto-close delay as MessageCloseDelay.DEFAULT in the GWT app. */
const CLOSE_DELAY_MS = 5000;

@Injectable({ providedIn: 'root' })
export class MessageService {
  readonly messages = signal<readonly AppMessage[]>([]);

  private nextId = 1;

  success(text: string): void {
    this.add('success', text);
  }

  error(text: string): void {
    this.add('error', text);
  }

  dismiss(id: number): void {
    this.messages.update((messages) => messages.filter((message) => message.id !== id));
  }

  private add(style: MessageStyle, text: string): void {
    const id = this.nextId++;
    this.messages.update((messages) => [...messages, { id, style, text }]);
    setTimeout(() => this.dismiss(id), CLOSE_DELAY_MS);
  }
}
