import { ChangeDetectionStrategy, Component, inject } from '@angular/core';

import { MessageService } from './message.service';

@Component({
  selector: 'app-messages',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="messages">
      @for (message of messageService.messages(); track message.id) {
        <div class="message"
             [class.success]="message.style === 'success'"
             [class.error]="message.style === 'error'"
             [id]="message.style === 'success' ? 'gwt-debug-successMessage' : 'gwt-debug-errorMessage'">
          <span>{{ message.text }}</span><span class="close" role="button" title="Close"
            (click)="messageService.dismiss(message.id)">X</span>
        </div>
      }
    </div>
  `,
  styles: `
    .messages {
      position: absolute;
      top: 30px;
      left: 50%;
      width: 300px;
      margin-left: -150px;
      z-index: 200;
    }
    .message {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 6px;
      padding: 8px 10px;
      border-radius: 3px;
      box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
    }
    .success {
      background: #dff0d8;
      color: #3c763d;
      border: 1px solid #b2dba1;
    }
    .error {
      background: #f2dede;
      color: #a94442;
      border: 1px solid #ebccd1;
    }
    .close {
      cursor: pointer;
      font-weight: bold;
      margin-left: 12px;
    }
  `,
})
export class MessagesComponent {
  readonly messageService = inject(MessageService);
}
